-- 1.4.0: the other languages, as BankaiGuild/Locales/<code>.lua had these lines before Bankai Guild Link left
-- the public addon. Not through ns.Locale, which keeps the report /bk status shows of Bankai Guild's own
-- language file: a line is taken only over an English one of this file, with the same format codes
-- (ns.LocaleCodes), as ns.Locale takes Bankai Guild's own; any other stays English.
local function Take(strings)
	local codes = ns.LocaleCodes
	for k, v in pairs(strings) do
		local en = rawget(L, k)
		if type(en) == "string" and type(v) == "string" and v ~= "" and (type(codes) ~= "function" or codes(v) == codes(en)) then
			L[k] = v
		end
	end
end
